using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Unity.Collections;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 [InitializeOnLoad] public static class TestMountainClearance {
  const string ScenePath="Assets/Scenes/AlpsTerrainTest.unity",Log="Logs/AlpsMountainClearance/";
  [Serializable] class Row {public string name;public float height,currentFloat,currentBurial,allowedBurial,bestYShift,bestBurial,minimumShift,maximumShift;public bool fitsVertically;public int rimSamples,surfaceSamples;}
  [Serializable] class Report {public Row[] mountains;}
  static TestMountainClearance(){EditorApplication.update+=Pending;}
  static void Check(bool v,string why){if(!v)throw new InvalidOperationException("Mountain clearance: "+why);}
  static void Pending(){const string marker="Logs/AlpsMountainClearance.request";if(!File.Exists(marker)||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;string action=File.ReadAllText(marker).Trim();File.Delete(marker);Directory.CreateDirectory(Log);try{if(action=="conform")Conform();else Run(action=="fit");}catch(Exception e){File.WriteAllText(Log+"Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static float Ground(MeshCollider terrain,Vector3 p){var b=terrain.bounds;Check(p.x>=b.min.x-.001f&&p.x<=b.max.x+.001f&&p.z>=b.min.z-.001f&&p.z<=b.max.z+.001f,"sample inside terrain");Check(terrain.Raycast(new Ray(new Vector3(Mathf.Clamp(p.x,b.min.x+.001f,b.max.x-.001f),b.max.y+20,Mathf.Clamp(p.z,b.min.z+.001f,b.max.z-.001f)),Vector3.down),out var hit,2000),"physical terrain under "+p);return hit.point.y;}
  static (Vector3[],Vector3[]) Samples(Transform root){var f=root.GetComponentsInChildren<MeshFilter>().Single();using(var data=MeshUtility.AcquireReadOnlyMeshData(f.sharedMesh)){var d=data[0];using(var v=new NativeArray<Vector3>(d.vertexCount,Allocator.Temp))using(var ix=new NativeArray<int>(d.GetSubMesh(0).indexCount,Allocator.Temp)){d.GetVertices(v);d.GetIndices(ix,0);var local=v.ToArray().Select(p=>root.InverseTransformPoint(f.transform.TransformPoint(p))).ToArray();float bottom=local.Min(p=>p.y);var ids=new Dictionary<Vector3Int,int>();var points=new List<Vector3>();var map=new int[local.Length];for(int i=0;i<local.Length;i++){var p=local[i];var key=new Vector3Int(Mathf.RoundToInt(p.x*1000),Mathf.RoundToInt(p.y*1000),Mathf.RoundToInt(p.z*1000));if(!ids.TryGetValue(key,out int id)){id=points.Count;ids.Add(key,id);points.Add(p);}map[i]=id;}var edgeUse=new Dictionary<(int,int),int>();var surface=new List<Vector3>(points.Select(p=>root.TransformPoint(p)));for(int k=0;k<ix.Length;k+=3){surface.Add(root.TransformPoint((local[ix[k]]+local[ix[k+1]]+local[ix[k+2]])/3));for(int e=0;e<3;e++){int a=map[ix[k+e]],b=map[ix[k+(e+1)%3]];var edge=(Mathf.Min(a,b),Mathf.Max(a,b));edgeUse.TryGetValue(edge,out int count);edgeUse[edge]=count+1;}}var rim=new List<Vector3>();foreach(var pair in edgeUse.Where(e=>e.Value==1)){var a=points[pair.Key.Item1];var b=points[pair.Key.Item2];if(a.y>bottom+.1f||b.y>bottom+.1f)continue;a=root.TransformPoint(a);b=root.TransformPoint(b);int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)));for(int k=0;k<=n;k++)rim.Add(Vector3.Lerp(a,b,k/(float)n));}Check(rim.Count>=24,"source open bottom perimeter "+root.name);return(rim.ToArray(),surface.ToArray());}}}
  static void Conform(){const string log="Logs/AlpsMountainBaseFit/";Directory.CreateDirectory(log);var scene=SceneManager.GetActiveScene();Check(scene.path==ScenePath,"current test scene only");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"),backup=log+"InMemory-before-"+stamp+".unity";Check(EditorSceneManager.SaveScene(scene,backup,true),"backup current user scene");File.Copy(ScenePath,log+"Disk-before-"+stamp+".unity");var group=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement");Check(group.transform.childCount==8,"eight supplied mountains");Check(group.GetComponentsInChildren<MeshFilter>().All(f=>AssetDatabase.GetAssetPath(f.sharedMesh).Contains("/AlpsMountainsV2/")),"unmodified V2 meshes; refuse repeat fitting");var terrain=scene.GetRootGameObjects().Single(g=>g.name=="Revised attached terrain | 1:1 metres").GetComponentInChildren<MeshCollider>();var folder=AssetDatabase.GenerateUniqueAssetPath("Assets/Snowglow/Levels/AlpsTerrainTest/FittedMountainBases");Directory.CreateDirectory(folder);AssetDatabase.Refresh();var report=new List<string>();int number=0,totalRemoved=0,totalTriangles=0;
   try{foreach(Transform t in group.transform){var f=t.GetComponentsInChildren<MeshFilter>().Single();var collider=t.GetComponentsInChildren<MeshCollider>().Single();var source=f.sharedMesh;var pose=t.position;var rotation=t.rotation;var scale=t.localScale;float height=Bounds(t.gameObject).size.y;Vector3[] vertices;Vector2[] uv;int[] indices;using(var data=MeshUtility.AcquireReadOnlyMeshData(source)){var d=data[0];Check(d.subMeshCount==1,"single source palette");using(var v=new NativeArray<Vector3>(d.vertexCount,Allocator.Temp))using(var u=new NativeArray<Vector2>(d.vertexCount,Allocator.Temp))using(var ix=new NativeArray<int>(d.GetSubMesh(0).indexCount,Allocator.Temp)){d.GetVertices(v);d.GetUVs(0,u);d.GetIndices(ix,0);vertices=v.ToArray();uv=u.ToArray();indices=ix.ToArray();}}
    var original=vertices.Select(v=>f.transform.TransformPoint(v)).ToArray();var local=original.Select(v=>t.InverseTransformPoint(v)).ToArray();float bottom=local.Min(v=>v.y);var ids=new Dictionary<Vector3Int,int>();var copies=new List<List<int>>();var map=new int[vertices.Length];for(int i=0;i<vertices.Length;i++){var v=local[i];var key=new Vector3Int(Mathf.RoundToInt(v.x*1000),Mathf.RoundToInt(v.y*1000),Mathf.RoundToInt(v.z*1000));if(!ids.TryGetValue(key,out int id)){id=copies.Count;ids.Add(key,id);copies.Add(new List<int>());}copies[id].Add(i);map[i]=id;}var use=new Dictionary<(int,int),int>();for(int k=0;k<indices.Length;k+=3)for(int e=0;e<3;e++){int x=map[indices[k+e]],y=map[indices[k+(e+1)%3]];var edge=(Mathf.Min(x,y),Mathf.Max(x,y));use.TryGetValue(edge,out int count);use[edge]=count+1;}var edges=use.Where(e=>e.Value==1&&local[copies[e.Key.Item1][0]].y<=bottom+.1f&&local[copies[e.Key.Item2][0]].y<=bottom+.1f).Select(e=>e.Key).ToArray();Check(edges.Length>=12,"true original bottom boundary");var rim=new HashSet<int>(edges.SelectMany(e=>new[]{e.Item1,e.Item2}));var world=(Vector3[])original.Clone();foreach(var c in copies){int i=c[0];float ground=Ground(terrain,world[i]);float y=rim.Contains(map[i])?ground-.5f:Mathf.Max(world[i].y,ground-.5f);foreach(int j in c)world[j].y=y;}
    for(int pass=0;pass<3;pass++)foreach(var edge in edges){var x=world[copies[edge.Item1][0]];var y=world[copies[edge.Item2][0]];int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(x,y)));float drop=0;for(int k=0;k<=n;k++){var v=Vector3.Lerp(x,y,k/(float)n);drop=Mathf.Max(drop,v.y-Ground(terrain,v)+.25f);}if(drop>0){foreach(int i in copies[edge.Item1])world[i].y-=drop;foreach(int i in copies[edge.Item2])world[i].y-=drop;}}
    float maxBurial=0,minRim=float.MaxValue;int sampleCount=0;foreach(var edge in edges){var x=world[copies[edge.Item1][0]];var y=world[copies[edge.Item2][0]];int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(x,y)));for(int k=0;k<=n;k++){var v=Vector3.Lerp(x,y,k/(float)n);float burial=Ground(terrain,v)-v.y;minRim=Mathf.Min(minRim,burial);maxBurial=Mathf.Max(maxBurial,burial);sampleCount++;}}Check(minRim>=.24f,"no floating perimeter");foreach(var v in world)maxBurial=Mathf.Max(maxBurial,Ground(terrain,v)-v.y);var kept=new List<int>();int removed=0;for(int k=0;k<indices.Length;k+=3){var x=world[indices[k]];var y=world[indices[k+1]];var z=world[indices[k+2]];foreach(var v in new[]{(x+y+z)/3,(x+y)/2,(y+z)/2,(z+x)/2}){maxBurial=Mathf.Max(maxBurial,Ground(terrain,v)-v.y);sampleCount++;}if(Vector3.Cross(y-x,z-x).sqrMagnitude<.00000001f){Check(new[]{x,y,z}.All(v=>v.y<=Ground(terrain,v)+.001f),"only remove hidden collapsed triangles");removed++;}else kept.AddRange(new[]{indices[k],indices[k+1],indices[k+2]});}Check(maxBurial<=height*.1f+.01f,"10percent maximum burial "+t.name+" actual="+maxBurial+" allowed="+height*.1f);int changed=0,aboveChanged=0;for(int i=0;i<world.Length;i++){Check(Mathf.Abs(world[i].x-original[i].x)<.00001f&&Mathf.Abs(world[i].z-original[i].z)<.00001f,"horizontal shape retained");if(Mathf.Abs(world[i].y-original[i].y)>.001f){changed++;if(original[i].y>Ground(terrain,original[i])+.01f)aboveChanged++;}vertices[i]=f.transform.InverseTransformPoint(world[i]);}Check(aboveChanged==0,"already exposed geometry retained");var mesh=new Mesh{name=t.name+" | terrain-fitted hidden base",indexFormat=source.indexFormat};mesh.vertices=vertices;mesh.uv=uv;mesh.triangles=kept.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/Mountain_"+(++number).ToString("D2")+".asset");f.sharedMesh=mesh;collider.sharedMesh=mesh;Check(t.position==pose&&t.rotation==rotation&&t.localScale==scale,"all root placements retained");totalRemoved+=removed;totalTriangles+=kept.Count/3;report.Add(t.name+" | original height="+height+"m | max burial="+maxBurial+"m ("+100*maxBurial/height+"%) | min rim burial="+minRim+"m | samples="+sampleCount+" | buried vertices adjusted="+changed+" | exposed vertices adjusted="+aboveChanged+" | triangles="+kept.Count/3+" | hidden collapsed triangles removed="+removed);}
    Physics.SyncTransforms();AssetDatabase.SaveAssets();Check(EditorSceneManager.SaveScene(scene,ScenePath),"save all fitted bases");scene=EditorSceneManager.OpenScene(ScenePath);terrain=scene.GetRootGameObjects().Single(g=>g.name=="Revised attached terrain | 1:1 metres").GetComponentInChildren<MeshCollider>();group=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement");Check(group.GetComponentsInChildren<MeshFilter>().All(f=>f.sharedMesh==f.GetComponent<MeshCollider>().sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).StartsWith(folder+"/",StringComparison.Ordinal)),"saved matching fitted render/collision meshes");CaptureFit(scene,log+"Overview.png",new Vector3(1150,850,0),Vector3.zero);int index=0;foreach(Transform t in group.transform){var b=Bounds(t.gameObject);var radial=new Vector3(t.position.x,0,t.position.z).normalized;for(int side=0;side<2;side++){var direction=Quaternion.Euler(0,side*65,0)*-radial;var at=b.center+direction*Mathf.Max(b.size.x,b.size.z)*1.4f;at.x=Mathf.Clamp(at.x,terrain.bounds.min.x+2,terrain.bounds.max.x-2);at.z=Mathf.Clamp(at.z,terrain.bounds.min.z+2,terrain.bounds.max.z-2);at.y=Mathf.Max(Ground(terrain,at)+5,b.min.y+b.size.y*.2f);CaptureFit(scene,log+"Mountain"+(index+1).ToString("D2")+"_"+side+".png",at,b.center);}index++;}EditorSceneManager.OpenScene(ScenePath);File.WriteAllText(log+"Validation.txt","PASS: all8 mountain bases fitted using new derivative meshes, preserving root XYZ/rotation/scale, horizontal geometry, exposed vertex positions, terrain and materials. Original welded bottom boundaries projected .5m under physical terrain; <=1m edge samples adjusted to stay >=.24m buried. All vertices, triangle centres/edge midpoints remain within10percent of original mountain height below terrain. Only buried lower geometry adjusted; no added vertices/triangles or artificial skirts. Hidden collapsed triangles removed="+totalRemoved+", fitted triangles="+totalTriangles+". Matching collision assigned; native save/reopen passed. Overview and16 base-level views generated. No Play/device acceptance.\n"+string.Join("\n",report));
   }catch(Exception e){File.WriteAllText(log+"Validation.txt","FAIL: "+e);if(SceneManager.GetActiveScene().isDirty)EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),log+"Failed-unsaved-"+stamp+".unity",true);File.Copy(backup,ScenePath,true);AssetDatabase.ImportAsset(ScenePath,ImportAssetOptions.ForceUpdate);EditorSceneManager.OpenScene(ScenePath);throw;}
  }
  static void CaptureFit(Scene scene,string path,Vector3 pos,Vector3 target){var source=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>()).Single();var go=new GameObject("Temporary fitted-base inspection");SceneManager.MoveGameObjectToScene(go,scene);var c=go.AddComponent<Camera>();c.CopyFrom(source);c.enabled=false;c.orthographic=false;c.fieldOfView=55;c.aspect=4f/3;c.farClipPlane=3000;c.layerCullDistances=new float[32];c.transform.SetPositionAndRotation(pos,Quaternion.LookRotation(target-pos));var rt=RenderTexture.GetTemporary(1200,900,24);var old=RenderTexture.active;var image=new Texture2D(1200,900,TextureFormat.RGB24,false);try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1200,900),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(go);}}
  static Bounds Bounds(GameObject g){var r=g.GetComponentsInChildren<MeshRenderer>();var b=r[0].bounds;foreach(var a in r.Skip(1))b.Encapsulate(a.bounds);return b;}
  static void Run(bool fit){var scene=SceneManager.GetActiveScene();Check(scene.path==ScenePath,"current test scene only");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Check(EditorSceneManager.SaveScene(scene,Log+"InMemory-before-"+stamp+".unity",true),"backup user scene");var group=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement");Check(group.transform.childCount==8,"eight mountains");var terrain=scene.GetRootGameObjects().Single(g=>g.name=="Revised attached terrain | 1:1 metres").GetComponentInChildren<MeshCollider>();var rows=new List<Row>();foreach(Transform t in group.transform){var samples=Samples(t);var bounds=Bounds(t.gameObject);float minRim=samples.Item1.Min(p=>Ground(terrain,p)-p.y),maxBurial=samples.Item2.Max(p=>Ground(terrain,p)-p.y);float height=bounds.size.y,upper=minRim-.25f,lower=maxBurial-height*.1f;var row=new Row{name=t.name,height=height,currentFloat=Mathf.Max(0,-minRim),currentBurial=Mathf.Max(0,maxBurial),allowedBurial=height*.1f,bestYShift=upper,bestBurial=Mathf.Max(0,maxBurial-upper),minimumShift=lower,maximumShift=upper,fitsVertically=lower<=upper+.001f,rimSamples=samples.Item1.Length,surfaceSamples=samples.Item2.Length};if(fit&&row.fitsVertically){var before=t.position;var rotation=t.rotation;var scale=t.localScale;var mesh=t.GetComponentInChildren<MeshFilter>().sharedMesh;t.position+=Vector3.up*upper;var after=Samples(t);Check(after.Item1.Min(p=>Ground(terrain,p)-p.y)>=.24f,"no floating rim");Check(after.Item2.Max(p=>Ground(terrain,p)-p.y)<=height*.1f+.01f,"at most10percent burial");Check(t.position.x==before.x&&t.position.z==before.z&&t.rotation==rotation&&t.localScale==scale&&t.GetComponentInChildren<MeshFilter>().sharedMesh==mesh,"Y-only fitting");}rows.Add(row);}if(fit){Physics.SyncTransforms();Check(EditorSceneManager.SaveScene(scene,ScenePath),"save feasible vertical fits");}File.WriteAllText(Log+(fit?"Fit.json":"Audit.json"),JsonUtility.ToJson(new Report{mountains=rows.ToArray()},true));File.WriteAllText(Log+"Validation.txt",(fit?"APPLIED feasible Y fits: ":"AUDIT only: ")+rows.Count(r=>r.fitsVertically)+"/8 can meet no-floating and10percent maximum burial using Y only. True welded open-rim edges sampled <=1m; all unique vertices and triangle centres checked for deep terrain penetration. No geometry/terrain/material edits.\n"+string.Join("\n",rows.Select(r=>r.name+" | height="+r.height+"m | float="+r.currentFloat+"m | burial="+r.currentBurial+"m | allowed="+r.allowedBurial+"m | best burial="+r.bestBurial+"m | Yfit="+r.fitsVertically)));}
 }
}
